diff --git a/src/ui/components/HashLink.tsx b/src/ui/components/HashLink.tsx
new file mode 100644
index 0000000..603a926
--- /dev/null
+++ b/src/ui/components/HashLink.tsx
@@ -0,0 +1,39 @@
+import type { CSSProperties, MouseEvent, ReactNode } from "react";
+import { isPlainLeftClick } from "../lib/plain-click.ts";
+import { serializeHash, type Selection } from "../lib/selection.ts";
+import { cn } from "../lib/utils.ts";
+
+/** Underline lives on the text node. A flex `HashLink` does not paint `hover:underline` on its children. */
+export const hashLinkText = "underline underline-offset-2";
+
+export function HashLink(props: {
+  selection: Selection;
+  onSelect: (selection: Selection) => void;
+  className?: string;
+  style?: CSSProperties;
+  children: ReactNode;
+  ariaLabel?: string;
+  ariaCurrent?: "page" | "location";
+}) {
+  return (
+    <a
+      href={serializeHash(props.selection)}
+      className={cn(
+        "focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:outline-none",
+        props.className,
+      )}
+      style={props.style}
+      aria-label={props.ariaLabel}
+      aria-current={props.ariaCurrent}
+      onClick={(event: MouseEvent<HTMLAnchorElement>) => {
+        if (!isPlainLeftClick(event)) {
+          return;
+        }
+        event.preventDefault();
+        props.onSelect(props.selection);
+      }}
+    >
+      {props.children}
+    </a>
+  );
+}

